package com.aistock.gateway;
import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.Test;import org.springframework.http.ResponseEntity;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class WatchlistProxyTest{
 @Test void deleteUsesDeleteVerbWithoutForwardingForgedOwner()throws Exception{var c=mock(UserPublicClient.class);when(c.delete(anyString(),anyMap(),anyMap())).thenAnswer(call->{assertEquals("users/me/watchlist/SH600030",call.getArgument(0));java.util.Map<String,String> h=call.getArgument(2);assertFalse(h.containsKey("X-User-Id"));assertEquals("token",h.get("X-XSRF-TOKEN"));return ResponseEntity.ok("{}".getBytes());});var mvc=MockMvcBuilders.standaloneSetup(new UserApiProxyController(c,new ObjectMapper())).build();mvc.perform(delete("/api/v1/users/me/watchlist/SH600030").header("X-User-Id","forged").header("X-XSRF-TOKEN","token")).andExpect(status().isOk());}
}
